window.NPC_CHUNK_2 = [{"name":"Jezeletrix","cr":8,"xp":4800,"race":"vulpinal agathion","age_category":"Adult","alignment":"CE","size":"Small","type":"outsider","sub_types":["agathion","extraplanar","good"],"templates_applied":"broken soul","init":6,"senses":["darkvision 60 ft.","low-light vision"],"ac":22,"ac_touch":13,"ac_flat_footed":20,"ac_mods":"+4 armor, +2 Dex, +5 natural, +1 size","hp":100,"hd":"8d10+56","hd_value":8,"fort":8,"ref":10,"will":9,"save_mods":"+4 vs. poison","dr":"5/-","immunities":["electricity","petrification"],"resists":["acid 5","cold 10","fire 5","sonic 10"],"sr":16,"weaknesses":["tormented"],"speed":[{"type":"land","speed":20}],"melee":"2 claws +11 (1d3+2), bite +11 (1d4+2) or torturous touch +11 touch (2d6 plus 1d6 Dex plus pain)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"agonized wail"},{"type":"baleful gaze"},{"type":"pounce"},{"type":"torturous touch"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":0,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect evil"},{"spell":"mage armor"},{"spell":"speak with animals"},{"spell":"tongues"}]},{"frequency":"1/day","spells":[{"spell":"charm monster"},{"spell":"dispel evil"},{"spell":"flame arrow"},{"spell":"holy smite"},{"spell":"major image"}]},{"frequency":"3/day","spells":[{"spell":"invisibility","details":"self only"},{"spell":"remove disease"},{"spell":"teleport","details":"self plus 50 lbs. of objects only"}]}],"strength":14,"dexterity":15,"constitution":23,"intelligence":18,"wisdom":16,"charisma":15,"baseatk":8,"cmb":9,"cmd":21,"feats":[{"feat":"Combat Reflexes"},{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":13},{"skill":"Bluff","value":13},{"skill":"Intimidate","value":10},{"skill":"Knowledge (arcana)","value":16},{"skill":"Knowledge (planes)","value":19},{"skill":"Perception","value":14},{"skill":"Perform (oratory)","value":13},{"skill":"Sense Motive","value":14},{"skill":"Spellcraft","value":15},{"skill":"Stealth","value":17},{"skill":"Use Magic Device","value":13}],"languages":["Common","Celestial","Draconic","Infernal; speak with animals","tongues"],"sq":["bardic knowledge","lay on hands"],"special_abilities":[{"type":"Agonized Wail","kind":"Su","details":"As a standard action, Jezeletrix can unleash a terrifying shriek. This affects all creatures with fewer than 8 Hit Dice within a 120-foot burst. Affected creatures must make a DC 16 Will save or become shaken until they move more than 120 ft. away from Jezeletrix. Those who successfully save are immune to this attack for 1 minute. This is a mind-affecting fear effect. The save DC is Charisma-based."},{"type":"Baleful Gaze","kind":"Su","details":"Any creature within 60 ft. who meets Jezeletrix's gaze must succeed on a DC 16 Fortitude save or take 1d4 points of Strength drain, 1d4 points of Constitution drain, and 1d4 points of Charisma drain. Whatever the result of the saving throw, a creature cannot be affected by the same broken soul's baleful gaze more than once per minute. The save DC is Charisma-based."},{"type":"Bardic Knowledge","kind":"Ex","details":"Jezeletrix gains a +4 bonus on all Knowledge checks, and can make Knowledge checks untrained."},{"type":"Lay on Hands","kind":"Su","details":"Once per day, Jezeletrix can heal 4d6 points of damage by touch (a standard action, unless she targets herself, in which case it's a swift action). This ability otherwise functions like the paladin's lay on hands ability."},{"type":"Tormented","kind":"Ex","details":"Jezeletrix takes a -10 penalty on concentration checks due to her wracking pain. Her wracking pains have also removed her vulpinal calm emotions aura."},{"type":"Torturous Touch","kind":"Su","details":"As a standard action, Jezeletrix can attempt this touch attack. The creature touched must succeed on a DC 16 Fortitude save or take 2d6 points of slashing damage and 1d6 points of Dexterity damage. In addition, the touched creature collapses to the ground in pain, falling prone and writhing on the ground, helpless, for 1d4 rounds. All of these effects are negated with a successful save. The save DC is Charisma-based."}],"before_combat":"If she hears intruders approaching her den, Jezeletrix becomes invisible.","during_combat":"Jezeletrix lost all of her gear, and without something to use flame arrow on, she opens combat with holy smite, followed by charm monster, in an attempt to neutralize the most heavily armored PC. She saves her agonized wail to use whenever she's surrounded, and in melee abandons her spells to focus on using her torturous touch.","morale":"Jezeletrix fights to the death.","source":"AP 28, The Great Beyond 62"},{"name":"Avahzi Serafian","cr":8,"xp":4800,"race":"elf","gender":"Female","age_category":"Adult","classes":[{"class":"cleric of Mammon","level":7},{"class":"diabolist","level":2}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["elf"],"init":3,"senses":["low-light vision"],"ac":24,"ac_touch":16,"ac_flat_footed":21,"ac_mods":"+8 armor, +3 Dex, +3 deflection, +1 shield","hp":69,"hd":"7d8+2d6+27","hd_value":9,"fort":8,"ref":6,"will":10,"save_mods":"+2 vs. enchantments","immunities":["sleep"],"resists":["acid 10"],"weaknesses":["damned"],"speed":[{"type":"land","speed":20}],"melee":"+1 shortspear +6 (1d6)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel hellfire"},{"type":"channel negative energy","details":"5/day, 4d6, Will DC 15"}],"spell_like_abilities_caster_level":7,"spell_like_abilities":[{"frequency":"7/day","spells":[{"spell":"acid dart"},{"spell":"touch of evil"}]}],"spellsknown_caster_level":9,"spellsknown_concentration":13,"spellsknown":[{"spell_level":5,"spell_slots":2,"spells":[{"spell":"flame strike"},{"spell":"wall of stone","type":"domain"}]},{"spell_level":4,"spell_slots":4,"spells":[{"spell":"air walk"},{"spell":"cure critical wounds"},{"spell":"freedom of movement"},{"spell":"unholy blight","type":"domain"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"bestow curse"},{"spell":"dispel magic"},{"spell":"magic vestment"},{"spell":"stone shape","type":"domain"},{"spell":"summon monster III"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"bear's endurance"},{"spell":"extended shield of faith"},{"spell":"resist energy"},{"spell":"soften earth and stone","type":"domain"},{"spell":"sound burst"},{"spell":"status"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"command"},{"spell":"cure light wounds","count":2},{"spell":"divine favor"},{"spell":"protection from good","type":"domain"},{"spell":"sanctuary"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"light"},{"spell":"purify food and drink"}]}],"spelldomains":"Earth, Evil","strength":8,"dexterity":16,"constitution":14,"intelligence":12,"wisdom":18,"charisma":14,"baseatk":6,"cmb":5,"cmd":21,"feats":[{"feat":"Channel Smite"},{"feat":"Combat Casting"},{"feat":"Command Undead"},{"feat":"Extend Spell"},{"feat":"Selective Channeling"}],"skills":[{"skill":"Knowledge (planes)","value":13},{"skill":"Knowledge (religion)","value":13},{"skill":"Spellcraft","value":13}],"languages":["Common","Elven","Infernal"],"sq":["elven magic","imp companion","infernal  charisma +2","infernal bargain","spontaneous casting (inflict spells)"],"special_abilities":[{"type":"Channel Hellfire","kind":"Su","details":"As a free action twice per day, Avahzi can alter a spell she casts that deals energy damage so that it instead deals hellfire damage. Spells altered in this way gain the lawful and evil descriptors. Hellfire damage is half fire damage and half damage from unholy energy. Evil-aligned creatures and creatures with the evil subtype take no damage from the unholy energy part of hellfire damage, but good-aligned creatures and creatures with the good subtype take double damage from the unholy energy. Protection from evil prevents all damage caused by the unholy damage portion of hellfire, but offers no protection from the fire damage."},{"type":"Damned","kind":"Ex","details":"If Avahzi is slain, her soul immediately travels to Hell. A character who attempts to return her to life must make a DC 12 caster level check or the spell fails."},{"type":"Infernal Bargain","kind":"Ex","details":"Avahzi can halve the price of servitude when she casts planar ally (or a similar spell) by successfully making an opposed Charisma check against a called (but not summoned) devil."},{"type":"Infernal Charisma","kind":"Ex","details":"Avahzi gains a +2 bonus on all Charismabased checks when interacting with devils."}],"gear":"masterwork breastplate, light steel shield, +1 shortspear, headband of inspired wisdom +2, gold holy symbol worth 120 gp, scroll of sending, wand of cure moderate wounds (15 charges), wand of spiritual weapon (7 charges)","before_combat":"Avahzi casts status on two randomly determined thieves every morning (often one stationed in area E1 and one in F1), along with magic vestment on her armor. The status effects serve as early warnings-if the PCs kill or harm one of these thieves, Avahzi knows to prepare. If she has time to prepare for a battle (such as if she notices intruders entering area F7), she casts air walk, bear's endurance, freedom of movement, and shield of faith on herself.","during_combat":"Avahzi hangs back in battle as long as she can, using her ranged spells to blast foes. She moves out into area F7 as soon as possible, and takes care to try to position herself so that she's between the PCs and the doors to F12 at all times.","morale":"If reduced to 20 or fewer hit points, Avahzi casts wall of stone between herself and the PCs to block off their easy access to area F12. She then flees to that area, casts sanctuary and resist energy (fire), and trusts to this to allow her a desperate flight through area F13. She hopes to race to the center of the Nessian Spiral, reach Liebdaga, and beg his aid before the PCs reach him themselves- how far she gets is left up to you.","base_statistics":"Base Statistics hp 51; Fort +6; Con 10","source":"AP 28, Princes of Darkness 44"},{"name":"Novankia","race":"imp","gender":"Female","age_category":"Adult","classes":[{"class":"animal companion","level":7}],"alignment":"LE","size":"Tiny","type":"outsider","sub_types":["devil","evil","extraplanar","lawful"],"init":5,"ac":25,"ac_touch":18,"ac_flat_footed":19,"ac_mods":"+5 Dex, +1 dodge, +7 natural, +2 size","hp":60,"hd":"8d10+16","hd_value":8,"fort":3,"ref":11,"will":7,"save_mods":"Will: +11 vs. enchantment","defensive_abilities":["devotion","evasion"],"speed":[{"type":"fly","speed":50,"maneuverability":"perfect"},{"type":"land","speed":20}],"melee":"sting +13 (1d4+1 plus poison)","space":"2-1/2 ft.","reach":"0 ft.","spell_like_abilities_caster_level":6,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"bleed"},{"spell":"invisibility","details":"self only"},{"spell":"prestidigitation"}]},{"frequency":"1/day","spells":[{"spell":"grease"},{"spell":"suggestion"}]},{"frequency":"1/week","spells":[{"spell":"commune","details":"CL 12th"}]}],"strength":13,"dexterity":20,"constitution":12,"intelligence":13,"wisdom":12,"charisma":14,"baseatk":6,"cmb":4,"cmd":20,"feats":[{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":28},{"skill":"Knowledge (arcana)","value":12},{"skill":"Perception","value":12}],"languages":["Celestial","Draconic","Infernal; telepathy 50 ft."],"sq":["change shape (raven, beast shape I)","link","share spells"],"special_abilities":[{"type":"Poison","kind":"Ex","details":"Injury-sting, save Fort DC 14, frequency 1/round for 6 rounds, effect 1d2 Dex, cure 1 save. The save DC is Constitution-based."}],"during_combat":"Novankia is aggressive in battle, eager to flap in to sting foes with Flyby Attacks. She returns to Avahzi's side to seek healing whenever reduced below 30 hit points.","morale":"Novankia follows Avahzi's lead, fighting as long as her mistress continues to do so, and fleeing only when she does.","source":"AP 28, Princes of Darkness 47"},{"name":"Tiefling Tunnel Rat","cr":2,"xp":600,"race":"Tiefling","age_category":"Adult","classes":[{"class":"fighter","level":3}],"alignment":"CE","size":"Medium","type":"outsider","sub_types":["native"],"init":2,"senses":["darkvision 60 ft."],"ac":17,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+4 armor, +2 Dex, +1 dodge","hp":33,"hd":"3d10+12","hd_value":3,"fort":5,"ref":3,"will":2,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1"],"resists":["cold 5","electricity 5","fire 5"],"speed":[{"type":"land","speed":30}],"melee":"sharpened tool +5 (1d8+3)","ranged":"rock +5 (1d4+2)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":3,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"darkness"}]}],"strength":15,"dexterity":15,"constitution":14,"intelligence":12,"wisdom":12,"charisma":6,"baseatk":3,"cmb":5,"cmd":17,"feats":[{"feat":"Catch Off-Guard"},{"feat":"Dodge"},{"feat":"Throw Anything"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":0},{"skill":"Climb","value":6},{"skill":"Knowledge (engineering)","value":7},{"skill":"Stealth","value":2},{"skill":"Survival","value":7}],"languages":["Common","Infernal"],"sq":["armor training 1","fiendish sorcery"],"gear":"hide armor, sharpened tool, throwing rocks (10)","during_combat":"The tieflings attack random targets-their madness and fear robbing them of the ability to coordinate sensible tactics.","morale":"These tieflings fight to the death.","source":"AP 28, Pathfinder RPG Bestiary 264"},{"name":"Joriavah","cr":9,"xp":6400,"race":"succubus","gender":"Female","age_category":"Adult","classes":[{"class":"cleric","level":3}],"alignment":"CE","size":"Medium","type":"outsider","sub_types":["chaotic","demon","evil","extraplanar"],"init":13,"senses":["darkvision 60 ft.","detect good"],"ac":26,"ac_touch":15,"ac_flat_footed":21,"ac_mods":"+4 armor, +4 Dex, +1 Dodge, +7 natural","hp":123,"hd":"8d10+3d8+66","hd_value":11,"fort":11,"ref":11,"will":13,"dr":"10/cold iron or good","immunities":["electricity","fire","poison"],"resists":["acid 10","cold 10"],"sr":18,"speed":[{"type":"fly","speed":50,"maneuverability":"average"},{"type":"land","speed":30}],"melee":"2 claws +13 (1d6+3)","ranged":"+1 frost hand crossbow +12 (2d4+7/19-20 plus 1d4 plus 1d6 cold)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel energy","details":"11/day, 2d6; Will DC 19"},{"type":"energy  drain","details":"1 level, DC 22"},{"type":"profane gift"}],"spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":11,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"tongues"}]},{"frequency":"at-will","spells":[{"spell":"charm monster"},{"spell":"detect thoughts"},{"spell":"ethereal jaunt","details":"self plus 50 lbs. of objects only"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"suggestion"},{"spell":"vampiric touch"}]},{"frequency":"1/day","spells":[{"spell":"dominate person"},{"spell":"summon","details":"1 babau 50%, level 3"}]},{"frequency":"7/day","spells":[{"spell":"dazing touch"}]}],"spellsprepared_caster_level":3,"spellsprepared_concentration":7,"spellsprepared":[{"spell_level":2,"spell_slots":3,"spells":[{"spell":"bear's endurance"},{"spell":"calm emotions","type":"domain"},{"spell":"cat's grace"}]},{"spell_level":1,"spell_slots":4,"spells":[{"spell":"cure light wounds","count":2},{"spell":"obscuring mist","type":"domain"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"guidance"},{"spell":"mending"}]}],"spelldomains":"Charm, Darkness","strength":17,"dexterity":19,"constitution":22,"intelligence":16,"wisdom":18,"charisma":27,"baseatk":10,"cmb":13,"cmd":28,"feats":[{"feat":"Blind-Fight"},{"feat":"Deadly Aim"},{"feat":"Dodge"},{"feat":"Exotic Weapon Proficiency (hand crossbow)"},{"feat":"Mobility"},{"feat":"Point-Blank Shot"},{"feat":"Shot on the Run"},{"feat":"Vital Strike"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Bluff","value":27},{"skill":"Diplomacy","value":16},{"skill":"Disguise","value":19},{"skill":"Escape Artist","value":15},{"skill":"Fly","value":15},{"skill":"Intimidate","value":19},{"skill":"Knowledge (local)","value":14},{"skill":"Knowledge (religion)","value":11},{"skill":"Perception","value":23},{"skill":"Sense Motive","value":15},{"skill":"Stealth","value":15}],"languages":["Common","Abyssal","Celestial","Draconic; tongues","telepathy 100 ft."],"sq":["spontaneous casting (inflict spells)"],"gear":"+1 studded leather armor, +1 frost hand crossbow with 20 bolts","during_combat":"Joriavah tries to dominate one of the PCs on the first round of combat (preferring to select a heavily armored character or an obvious healer) and orders that character to attack his friends. She then teleports away to an abandoned house elsewhere in Westcrown (one of many such locations she's already explored), where she takes the time to try to summon a babau and cast bear's endurance, cat's grace, and shield of faith before she teleports back to area F10 to attack the PCs with her crossbow at range (using Shot on the Run, Vital Strike, and Deadly Aim to full effect to maintain ranged superiority). In melee, she relies on vampiric touch each round.","morale":"If brought below 30 hit points, Joriavah teleports to one of her abandoned houses to recover; once she's healed up, she returns to the Nessian Spiral, becomes ethereal, and seeks out the PCs for revenge, repeating her fight-and-retreat tactics until the PCs are dead or they prevent her escape and kill her.","source":"AP 28, Nocticula"},{"name":"Dargentu Vheed","cr":9,"xp":6400,"race":"lich shade","gender":"Male","age_category":"Adult","alignment":"NE","size":"Medium","type":"undead","init":8,"senses":["darkvision 60 ft.","spell sense 100 ft."],"ac":20,"ac_touch":15,"ac_flat_footed":15,"ac_mods":"+4 Dex, +3 deflection, +1 dodge, +5 natural","hp":104,"hd":"11d8+55","hd_value":11,"fort":10,"ref":9,"will":12,"defensive_abilities":["channel resistance +2"],"dr":"10/bludgeoning and magic","immunities":["undead traits"],"resists":["cold 10","electricity 10"],"sr":19,"speed":[{"type":"land","speed":30}],"melee":"2 claws +15 (1d6+7 plus 1d6 cold)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"chill"},{"type":"death throes"},{"type":"spell leech"}],"strength":24,"dexterity":19,"intelligence":19,"wisdom":16,"charisma":20,"baseatk":8,"cmb":15,"cmd":30,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Intimidate","value":19},{"skill":"Knowledge (arcana)","value":18},{"skill":"Knowledge (religion)","value":18},{"skill":"Perception","value":17},{"skill":"Sense Motive","value":19},{"skill":"Spellcraft","value":18},{"skill":"Stealth","value":20},{"skill":"Use Magic Device","value":16}],"languages":["Common","Infernal"],"special_abilities":[{"type":"Chill","kind":"Su","details":"Dargentu's claws inflict an additional 1d6 points of cold damage on a hit, and any creature that takes this additional cold damage must make a DC 20 Fortitude save or be staggered for 1 round by the numbing chill. The save DC is Charisma-based."},{"type":"Death Throes","kind":"Su","details":"When Dargentu is destroyed, he explodes into a burst of choking dust. All creatures within 10 ft. must make a DC 20 Fortitude save or take 1d6 points of Constitution damage from the violent choking and necromantic scouring of this supernaturally vile dust. Those who fail the save are also nauseated for 1d6 rounds, while those who succeed are merely sickened for 1d6 rounds. The save DC is Charisma-based."},{"type":"Spell Leech","kind":"Su","details":"Whenever a spellcaster within 50 ft. of Dargentu casts a spell, the spellcaster must make a DC 20 Will save or the spell is lost, as if it were counterspelled. The lost spell's energy is transferred to Dargentu, who can use the magical energy in one of the following three ways. Dargentu can only store the energy of one spell at a time. Cast: Dargentu can cast the spell on his turn at caster level 11th. When casting spells in this manner, he ignores the spell's material component requirements, but not its focus requirements. Eldritch Bolt: Dargentu can release the spell as an eldritch bolt of pure magic energy as a standard action (range 50 ft., ranged touch +12, 1d6 damage per 2 levels of the spell used to create it). Healing: Dargentu can absorb the spell's energy to heal hit points equal to the spell's level x4. Hit points in excess of his maximum are instead gained as temporary hit points. These temporary hit points last for 1 hour before fading."},{"type":"Spell Sense","kind":"Su","details":"Dargentu can automatically pinpoint the location of any spellcaster within 100 ft. who has cast a spell within the previous round. He can also identify spells as they are being cast and all existing spell effects as if he were under the effects of greater arcane sight."}],"gear":"ring of protection +3, ring of wizardry I","during_combat":"As soon as Dargentu notices intruders (either with his spell sense, by someone shutting down the capacitor at area F14, or by sight), he moves at once to attack-moving to area F14 if no obvious foe can be pinpointed. He focuses his attacks on non-spellcasters, hoping to give spellcasters more opportunities to cast so he can use his spell leech powers and revel in the act of once again being able to cast spells. In most cases, Dargentu opts to cast spells he absorbs unless there's no use for them, in which case he heals (if he's damaged) or uses an eldritch bolt.","morale":"Dargentu fights until destroyed.","source":"AP 28, Tome of Horrors III 117"},{"name":"Achaierai","cr":5,"xp":1600,"race":"Achaierai","age_category":"Adult","alignment":"LE","size":"Large","type":"outsider","sub_types":["evil","extraplanar","lawful"],"init":1,"senses":["darkvision 60 ft."],"ac":20,"ac_touch":11,"ac_flat_footed":18,"ac_mods":"+1 Dex, +1 dodge, +9 natural, -1 size","hp":52,"hd":"7d10+14","hd_value":7,"fort":7,"ref":6,"will":4,"sr":20,"speed":[{"type":"land","speed":50}],"melee":"2 claws +10 (1d6+4), bite +10 (2d6+4)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"black cloud"}],"strength":19,"dexterity":13,"constitution":14,"intelligence":11,"wisdom":14,"charisma":16,"baseatk":7,"cmb":12,"cmd":24,"feats":[{"feat":"Dodge"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Climb","value":14},{"skill":"Perception","value":12},{"skill":"Sense Motive","value":12},{"skill":"Stealth","value":7},{"skill":"Swim","value":14}],"languages":["Infernal"],"special_abilities":[{"type":"Black Cloud","kind":"Su","details":"An achaierai can exhale a cloud of choking, toxic smoke three times per day. Any non-achaierai within 10 ft. of the achaierai immediately takes 2d6 points of damage as its tissues burn and melt and rot away. The cloud erodes sanity as well as flesh, and anyone who takes damage from the black cloud must also make a DC 15 Fortitude save or become confused. Every round, the victim may attempt another DC 15 Fortitude save to recover from the confusion; otherwise it persists, lasting indefinitely until the condition is removed or the victim eventually makes his saving throw. The confusion element of a black cloud is a mind-affecting effect. The save DC is Constitution-based."}],"during_combat":"The achaierais open combat with their black clouds, then close to engage the PCs in melee. They are smart enough to try to pin down foes within the confines of the razor sharp thorns when they can.","morale":"The achaierais fight to the death.","source":"AP 28"},{"name":"Burning Guardian","cr":8,"xp":4800,"race":"stone guardian golem","age_category":"Adult","alignment":"N","size":"Large","type":"construct","sub_types":["fire"],"templates_applied":"advanced, fire infused","init":-1,"senses":["darkvision 60 ft.","low-light vision","see invisibility"],"ac":17,"ac_touch":8,"ac_flat_footed":17,"ac_mods":"-1 Dex, +9 natural, -1 size","hp":96,"hd":"12d10+30","hd_value":12,"fort":4,"ref":3,"will":2,"defensive_abilities":["fire healing","light fortification"],"immunities":["construct traits","fire"],"resists":["cold 5","electricity 5"],"weaknesses":["vulnerable to cold"],"speed":[{"type":"land","speed":20}],"speed_mod":"firewalk","melee":"2 slams +20 (2d6+9)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"breath weapon","details":"30-foot cone, 6d6 fire damage, Reflex DC 16 for half, usable once every 1d4 rounds"}],"strength":28,"dexterity":9,"wisdom":7,"charisma":3,"baseatk":12,"cmb":22,"cmd":31,"special_abilities":[{"type":"Fire Healing","kind":"Ex","details":"The burning guardian gains fast healing 1 each round it remains in contact with fire. When struck by a magical fire effect, it heals 1 point of damage per 10 points of damage the fire effect would otherwise deal."},{"type":"Firewalk","kind":"Su","details":"The burning guardian can climb on an object on fire as though it had a climb speed of 20 feet. It can fly at a speed of 20 ft. with perfect maneuverability so long as it remains in contact with fire, and can walk on flames at normal speed as though walking on air via the air walk spell."},{"type":"Light Fortification","kind":"Ex","details":"The burning guardian has a 25% chance to ignore additional damage caused by critical hits or sneak attacks."},{"type":"Ring Link","kind":"Su","details":"The burning guardian is linked to a magic ring. The construct will never attack any creature that wears this ring, nor any creatures within 10 ft. of the ringwearer, unless one of those creatures attacks the guardian first."},{"type":"See Invisibility","kind":"Ex","details":"The burning guardian constantly sees invisible creatures and objects, as per the spell see invisibility."}],"during_combat":"The burning guardian makes sure to stand so that at least one square of its space is one of the shallow fire pits-these pits are difficult terrain for the guardian to walk through, but grant it fast healing as long as it remains within the area.","morale":"The burning guardian fights until destroyed.","source":"AP 28, Tome of Horrors Revised 220, Advanced Bestiary 111"},{"name":"Signatory Vaccha","cr":12,"xp":19200,"race":"Kolyarut inevitable","age_category":"Adult","alignment":"LN","size":"Medium","type":"outsider","sub_types":["extraplanar","inevitable","lawful"],"init":8,"senses":["darkvision 60 ft.","low-light vision"],"ac":26,"ac_touch":14,"ac_flat_footed":22,"ac_mods":"+4 Dex, +12 natural","hp":161,"hd":"14d10+84","hd_value":14,"hp_mods":"fast healing 5","fort":12,"ref":10,"will":7,"dr":"10/chaotic","immunities":["construct traits"],"sr":22,"speed":[{"type":"land","speed":30}],"melee":"2 slams +20 (2d6+6)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"discern lies"},{"spell":"disguise self"},{"spell":"enervation"},{"spell":"fear"},{"spell":"hold person"},{"spell":"invisibility","details":"self only"},{"spell":"locate creature"},{"spell":"suggestion"},{"spell":"vampiric touch"}]},{"frequency":"1/day","spells":[{"spell":"hold monster"},{"spell":"mark of justice"},{"spell":"quickened suggestion"}]},{"frequency":"1/week","spells":[{"spell":"geas/quest"}]}],"strength":22,"dexterity":19,"constitution":23,"intelligence":10,"wisdom":17,"charisma":16,"baseatk":14,"cmb":20,"cmd":34,"feats":[{"feat":"Alertness"},{"feat":"Combat Casting"},{"feat":"Combat Reflexes"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Quicken Spell-Like Ability (suggestion)"}],"skills":[{"skill":"Diplomacy","value":20},{"skill":"Disguise","value":20},{"skill":"Knowledge (planes)","value":17},{"skill":"Linguistics","value":17},{"skill":"Perception","value":24},{"skill":"Sense Motive","value":24}],"languages":["truespeech"],"sq":["constructed"],"special_abilities":[{"type":"Constructed","kind":"Ex","details":"Although a kolyarut is a living outsider, its body is constructed of physical components-in many ways, it functions as a construct rather than a living creature. For the purposes of a ranger's favored enemy and bane weapons, a kolyarut is treated as both an outsider and a construct. It is immune to death effects, disease, mindaffecting effects, necromancy effects, paralysis, poison, sleep, stun, and any effect that requires a Fortitude save (unless the effect also works on objects, or is harmless). It isn't subject to nonlethal damage, ability damage, ability drain, fatigue, exhaustion, or energy drain. It isn't at risk of death from massive damage."},{"type":"Truespeech","kind":"Su","details":"A kolyarut can speak with any creature that has a language, as if using a tongues spell (caster level 14th). This ability is always active."}],"during_combat":"The kolyarut doesn't necessarily want to slay intruders-merely drive them off. It relies on fear and quickened suggestions, switching to more deadly methods such as its slam or vampiric touch to destroy foes who prove resistant to mental effects.","morale":"Signatory Vaccha fights to the death.","source":"AP 28"},{"name":"Zovarue","cr":10,"xp":9600,"race":"medusa","gender":"Female","age_category":"Adult","classes":[{"class":"sorcerer","level":7}],"alignment":"LE","size":"Medium","type":"monstrous humanoid","init":5,"senses":["all-around vision","darkvision 60 ft."],"ac":23,"ac_touch":15,"ac_flat_footed":18,"ac_mods":"+4 armor, +4 Dex, +1 dodge, +4 natural","hp":120,"hd":"8d10+7d6+60","hd_value":15,"fort":8,"ref":12,"will":13,"save_mods":"+2 vs. poison","resists":["fire 10"],"speed":[{"type":"land","speed":30}],"melee":"+1 mithral dagger +16 (1d4+4/19- 20), snake bite +15 (1d4+3 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"petrifying gaze","details":"30 ft., DC 18"},{"type":"poison","details":"DC 18, 1/round for 6 rounds, 1d3 Str,  cure 2 consecutive saves"}],"spell_like_abilities_caster_level":7,"spell_like_abilities":[{"frequency":"8/day","spells":[{"spell":"corrupting touch"}]}],"spellsknown_caster_level":7,"spellsknown_concentration":12,"spellsknown":[{"spell_level":3,"spell_slots":5,"spells":[{"spell":"displacement"},{"spell":"suggestion"},{"spell":"water breathing"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"acid arrow"},{"spell":"resist energy"},{"spell":"scorching ray"},{"spell":"spider climb"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"feather fall"},{"spell":"floating disc"},{"spell":"grease"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"protection from good"},{"spell":"silent image"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"bleed"},{"spell":"detect magic"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"bloodline":"infernal","strength":12,"dexterity":19,"constitution":18,"intelligence":10,"wisdom":15,"charisma":21,"baseatk":11,"cmb":12,"cmd":26,"feats":[{"feat":"Arcane Strike"},{"feat":"Blind-Fight"},{"feat":"Combat Casting"},{"feat":"Craft Wondrous Item"},{"feat":"Dodge"},{"feat":"Empower Spell"},{"feat":"Eschew Materials"},{"feat":"Extend Spell"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":16},{"skill":"Knowledge (arcana)","value":10},{"skill":"Knowledge (engineering)","value":7},{"skill":"Perception","value":17},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":15}],"languages":["Common"],"sq":["bloodline arcana"],"gear":"+1 mithral dagger, headband of alluring charisma +2, amulet of natural armor +1, wand of make whole (CL 10th, 16 charges)","before_combat":"Zovarue casts extended mage armor when she wakes each day.","during_combat":"In combat, Zovarue lifts her veil (a free action)  and casts displacement. She follows up with her offensive spells or melee attacks using Arcane Strike.","morale":"Zovarue fights to the death.","source":"AP 28"},{"name":"Liebdaga's Cage","cr":8,"xp":4800,"race":"animated object","age_category":"Adult","alignment":"N","size":"Medium","type":"construct","templates_applied":"advanced","init":1,"senses":["darkvision 60 ft.","low-light vision"],"ac":22,"ac_touch":10,"ac_flat_footed":21,"ac_mods":"+1 Dex, +12 natural, -1 size","hp":52,"hd":"4d10+30","hd_value":4,"fort":1,"ref":2,"will":-2,"defensive_abilities":["hardness 20"],"immunities":["construct traits","fire"],"speed":[{"type":"land","speed":30}],"speed_mod":"chained","melee":"3 slams +11 (1d8+8 plus 1d6 fire plus grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"constrict","details":"1d8+8 plus 1d6 fire"}],"strength":26,"dexterity":12,"wisdom":5,"charisma":5,"baseatk":4,"cmb":13,"cmb_special":"+17 grab","cmd":24,"special_abilities":[{"type":"Chained","kind":"Ex","details":"Liebdaga's cage can effectively move at a speed of 30 ft. as if under the effects of air walk, as it moves by shifting its position in the room by lengthening or shortening the chains that hold it in the room. It cannot leave area F37 at all."}],"during_combat":"The cage cannot leave this chamber, and remains animated as long as there are visible targets. The cage itself is red hot, and inflicts additional fire damage on each hit. In addition, for every cooling chamber left active, the cage gains 2 points of fast healing-the stats here assume all five cooling chambers are deactivated.","morale":"The cage fights until destroyed.","source":"AP 28, Pathfinder RPG Bestiary 14"},{"name":"Liebdaga the Twin","cr":12,"xp":19200,"race":"weakened pit fiend duke","gender":"Male","age_category":"Adult","alignment":"LE","size":"Large","type":"outsider","sub_types":["devil","evil","extraplanar","lawful"],"init":8,"senses":["darkvision 60 ft.","see in darkness"],"ac":28,"ac_touch":13,"ac_flat_footed":24,"ac_mods":"+4 Dex, +15 natural, -1 size","hp":137,"hd":"13d10+91","hd_value":13,"hp_mods":"fast healing 5","fort":10,"ref":3,"will":10,"defensive_abilities":["tenacious soul"],"dr":"10/good or silver Immune fire, poison","resists":["acid 10","cold 10"],"sr":22,"weaknesses":["negative levels","staggered"],"speed":[{"type":"land","speed":40}],"melee":"2 claws +15 (2d8+8), 2 wings +10 (2d6+4), bite +15 (4d6+8 plus poison and disease), tail +15 (2d8+8 plus grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"constrict","details":"2d8+12"},{"type":"devil shaping"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":9,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"greater scrying"}]},{"frequency":"1/day","spells":[{"spell":"fireball"},{"spell":"greater dispel magic"},{"spell":"scorching ray"},{"spell":"wall of fire"}]}],"strength":27,"dexterity":19,"constitution":25,"intelligence":16,"wisdom":20,"charisma":16,"baseatk":13,"cmb":17,"cmd":31,"feats":[{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":14},{"skill":"Diplomacy","value":14},{"skill":"Fly","value":-5},{"skill":"Intimidate","value":14},{"skill":"Knowledge (arcana)","value":14},{"skill":"Knowledge (planes)","value":14},{"skill":"Knowledge (religion)","value":11},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":16},{"skill":"Spellcraft","value":14}],"languages":["Common","Celestial","Draconic","Infernal","telepathy 100 ft."],"special_abilities":[{"type":"Negative Levels","kind":"Ex","details":"Every cooling chamber the PCs shut down imparts a permanent negative level upon Liebdaga. This stat block assumes that all five cooling chambers are shut down, and that the pit fiend has five permanent negative levels. You should adjust his stats as appropriate if this isn't the case."},{"type":"Staggered","kind":"Ex","details":"Liebdaga is staggered, but as a standard action, he can focus his thoughts so that on the round immediately following he can act as if not staggered. The round after he acts as if not staggered, he becomes nauseated for 1 round, after which he returns to his normal, non-nauseated staggered condition. While focusing his thoughts, Liebdaga is considered flat-footed."},{"type":"Tenacious Soul","kind":"Su","details":"As an infernal duke, Liebdaga possesses an additional power beyond most pit fiends-his tenacious soul. This grants Liebdaga complete immunity to mindaffecting effects, but more impressively it allows him to recover from even the most devastating of wounds. If reduced to -25 hit points, the pit fiend dies, but a smoky, ghostly devilish form rises from his wounds-the pit fiend's soul. On the pit fiend's next action, his soul targets the body with a breath of life spell effect (CL 12th), healing the downed pit fiend 5d8+12 points of damage. If this healing brings his hit point total back up to -25 or higher, his fast healing kicks in-if it restores him to positive hit points, he revives and can continue to fight. If his soul is unable to restore the body to at least -25 hit points, the pit fiend is truly dead. At this point, the soul shrieks in frustration and rage-all creatures within 30 ft. must make a DC 19 Will save or suffer 1d6 points of Charisma damage from this soul-shattering, madness-inducing howl (the save DC is Charisma-based), after which Liebdaga's soul moves on to Hell and must begin anew as a mass of mindless lemures- this effectively ends Liebdaga for good, preventing him not only from returning to Westcrown to seek revenge, but from ever returning to power in Hell itself."}],"during_combat":"Liebdaga opens combat by casting fireball at the densest group of PCs. On the second round of combat, he takes a round to focus his thoughts so that on the third round of combat he can make a full attack action. He repeats these tactics, saving his spell-like abilities to use against foes if he can't engage them in melee.","morale":"Liebdaga has no choice as long as he remains imprisoned or bound to area F37, and fights to the death as a result.","source":"AP 28, Pathfinder RPG Bestiary 80"},{"name":"Zol","cr":10,"xp":9600,"race":"half-Orc","gender":"Male","age_category":"Adult","classes":[{"class":"barbarian","level":1},{"class":"monk","level":10}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human","orc"],"init":3,"senses":["darkvision 60 ft."],"ac":25,"ac_touch":20,"ac_flat_footed":21,"ac_mods":"+1 armor, +2 deflection, +3 Dex, +1 dodge, +2 monk, +4 natural, +2 Wis","hp":90,"hd":"1d12+10d8+33","hd_value":11,"fort":11,"ref":10,"will":11,"save_mods":"+2 vs. enchantments","defensive_abilities":["improved evasion","Orc ferocity","slow fall 50 ft."],"immunities":["disease"],"speed":[{"type":"land","speed":70}],"melee":"flurry of blows +13 (1d10+4/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"ki pool","details":"9 points"},{"type":"Stunning Fist","details":"10/day, DC 17"}],"strength":18,"dexterity":16,"constitution":14,"intelligence":10,"wisdom":14,"charisma":8,"baseatk":8,"cmb":12,"cmb_special":"+14 trip","cmd":33,"cmd_special":"35 vs. trip","feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Extra Ki"},{"feat":"Improved Critical (unarmed strike)"},{"feat":"Improved Trip"},{"feat":"Improved Unarmed Strike"},{"feat":"Iron Will"},{"feat":"Step Up"},{"feat":"Stunning Fist"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (unarmed strike)"}],"skills":[{"skill":"Acrobatics","value":17,"special":"+10 jump"},{"skill":"Climb","value":18},{"skill":"Intimidate","value":15},{"skill":"Perception","value":16},{"skill":"Stealth","value":16}],"languages":["Common","Orc"],"sq":["high jump","maneuver training","Orc blood"],"gear":"belt of physical might +2 (Str/Con), bracers of armor +1, ring of protection +2, potion of barkskin +4 (2)","during_combat":"Zol moves in to fight foes in melee, spending a ki point each round to increase his AC by +4 but leaving his last point unspent for emergencies.","morale":"Zol fights to the death.","source":"AP 28"},{"name":"Maven Mosslight","cr":10,"xp":9600,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"sorcerer","level":9}],"alignment":"NE","size":"Medium","type":"undead","sub_types":["augmented humanoid","human","incorporeal"],"templates_applied":"ghost","init":7,"senses":["darkvision 60 ft."],"ac":19,"ac_touch":19,"ac_flat_footed":15,"ac_mods":"+3 Dex, +1 dodge, +5 deflection","hp":94,"hd":"9d6+63","hd_value":9,"fort":8,"ref":8,"will":7,"defensive_abilities":["channel resistance +4","incorporeal","rejuvenation"],"immunities":["undead traits"],"resists":["cold 20"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"corrupting touch +7 (10d6, Fort DC 19 half)","ranged":"elemental ray +7 (1d6+4 cold)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"elemental blast"},{"type":"telekinesis","details":"CL 12th, Will DC 19"}],"spell_like_abilities_caster_level":9,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"elemental blast"}]},{"frequency":"8/day","spells":[{"spell":"elemental ray"}]}],"spellsknown_caster_level":9,"spellsknown":[{"spell_level":4,"spell_slots":5,"spells":[{"spell":"bestow curse"},{"spell":"elemental body"},{"spell":"solid fog"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"protection from energy"},{"spell":"ray of exhaustion"},{"spell":"stinking cloud"},{"spell":"water breathing"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"command undead"},{"spell":"gust of wind"},{"spell":"invisibility"},{"spell":"scorching ray"},{"spell":"summon swarm"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"animate rope"},{"spell":"burning hands"},{"spell":"cause fear"},{"spell":"hold portal"},{"spell":"silent image"},{"spell":"sleep"}]},{"spell_level":0,"spell_slots":8,"spells":[{"spell":"acid splash"},{"spell":"bleed"},{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"message"},{"spell":"open/close"},{"spell":"prestidigitation"}]}],"bloodline":"elemental (water)","dexterity":16,"intelligence":12,"wisdom":13,"charisma":21,"baseatk":4,"cmb":4,"cmd":23,"feats":[{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Improved Lightning Reflexes"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":12},{"skill":"Fly","value":8},{"skill":"Intimidate","value":14},{"skill":"Knowledge (arcana)","value":7},{"skill":"Knowledge (local)","value":2},{"skill":"Knowledge (nature)","value":9},{"skill":"Knowledge (nobility)","value":6},{"skill":"Perception","value":21},{"skill":"Stealth","value":15}],"languages":["Common","Hallit"],"sq":["grave trappings"],"special_abilities":[{"type":"Corrupting Touch","kind":"Su","details":"By passing part of its incorporeal body through a foe's body as a standard action, Maven inflicts 10d6 damage. This damage isn't negative energy-it manifests in the form of physical wounds and aches from supernatural aging. Creatures immune to magical aging are immune to this damage, but otherwise the damage bypasses all forms of damage reduction. A Fortitude save (DC 19) halves the damage inflicted."},{"type":"Grave Trappings","kind":"Su","details":"Maven bears a ghostly lantern that sheds an unnerving glow. This light functions like a candle of invocation, causing all evil creatures that come within 30 ft. of Maven to gain a +2 morale bonus on attack rolls, saving throws, and skill checks. Once per day she can use the candle to summon 1d4 will-o'-wisps. Maven can interact with the lantern as though it were incorporeal. If Maven is destroyed, the lantern is destroyed as well, and reforms with her upon rejuvenating."},{"type":"Rejuvenation","kind":"Su","details":"If \"destroyed\" through combat, Maven restores herself in 2d4 days. She can only be put to rest if her sunken, fish-eaten remains and the richly interred corpse of Lady Sylnia Whitchaste have their places swapped."},{"type":"Telekinesis","kind":"Su","details":"Maven can use telekinesis as a standard action once every 1d4 rounds (caster level 12th)."}],"gear":"lantern of souls (grave trappings)","source":"Classic Horrors"},{"name":"Evehxa, Derro Magister","cr":8,"xp":3200,"race":"derro","gender":"Female","age_category":"Adult","classes":[{"class":"sorcerer","level":6}],"alignment":"CE","size":"Small","type":"humanoid","init":4,"senses":["darkvision 60 ft."],"ac":21,"ac_touch":16,"ac_flat_footed":7,"ac_mods":"+3 armor, +1 deflection, +4 Dex, +2 natural, +1 size","hp":70,"hd":"3d8+6d6+36","hd_value":9,"fort":7,"ref":7,"will":14,"sr":14,"weaknesses":["susceptible to sunlight"],"speed":[{"type":"land","speed":20}],"melee":"+1 aklys +11 (1d6)","ranged":"+1 aklys +11 (1d6)","space":"5 ft.","reach":"5 ft. (10 ft. with melee touch attacks)","special_attacks":[{"type":"bloodline arcana","details":"increase polymorph  subschool duration by 50%"},{"type":"sneak attack","details":"+1d6"}],"spell_like_abilities_caster_level":3,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"darkness"},{"spell":"ghost sound"}]},{"frequency":"1/day","spells":[{"spell":"daze"},{"spell":"sound burst"}]},{"frequency":"9/day","spells":[{"spell":"acidic ray","details":"1d6+3 acid damage, 30 ft."}]}],"spellsknown_caster_level":6,"spellsknown":[{"spell_level":3,"spell_slots":4,"spells":[{"spell":"hold person"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"alter self"},{"spell":"invisibility"},{"spell":"see invisibility"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"charm person"},{"spell":"enlarge person"},{"spell":"hypnotism"},{"spell":"ray of enfeeblement"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"bleed (DC 16) detect magic"},{"spell":"dancing lights"},{"spell":"mage hand"},{"spell":"message"}]}],"bloodline":"aberrant","strength":9,"dexterity":18,"constitution":18,"intelligence":14,"wisdom":5,"charisma":22,"baseatk":5,"cmb":3,"cmd":17,"feats":[{"feat":"Arcane Armor Training"},{"feat":"Brew Potion"},{"feat":"Derro Magic"},{"feat":"Derro Magister"},{"feat":"Eschew Materials"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Craft (alchemy)","value":14},{"skill":"Heal","value":7},{"skill":"Knowledge (arcana)","value":7},{"skill":"Knowledge (dungeoneering)","value":7},{"skill":"Perception","value":6},{"skill":"Spellcraft","value":7},{"skill":"Stealth","value":17}],"languages":["Common","Aklo","Terran","Undercommon"],"sq":["long limbs","madness","poison use"],"special_abilities":[{"type":"Madness","kind":"Ex","details":"Derros use their Charisma modifier on Will saves instead of their Wisdom modifier, and are immune to insanity and confusion effects. Only a miracle or wish can remove a derro's madness. If this occurs, the derro gains 6 points of Wisdom and loses 6 points of Charisma."},{"type":"Poison Use","kind":"Ex","details":"Derros are not at risk of poisoning themselves when handling poison."},{"type":"Vulnerability to Sunlight","kind":"Ex","details":"A derro takes 1 point of Con damage after every hour it is exposed to sunlight."}],"gear":"+1 leather armor, +1 aklys, handy haversack, ring of protection +1, cytillesh extract (2 doses)","source":"Classic Horrors, Pathfinder RPG Bestiary 70"},{"name":"The Beast of Lepidstadt","cr":13,"xp":25600,"race":"Flesh golem","age_category":"Adult","classes":[{"class":"barbarian","level":6}],"alignment":"N","size":"Large","type":"construct","init":-1,"senses":["darkvision 60 ft.","low-light vision"],"ac":23,"ac_touch":6,"ac_flat_footed":23,"ac_mods":"+5 armor, -1 Dex, +12 natural, -2 rage, -1 size","hp":118,"hd":"9d10+6d12+30","hd_value":15,"fort":8,"ref":4,"will":10,"defensive_abilities":["improved uncanny dodge","trap sense +2"],"dr":"5/adamantine","immunities":["construct traits","magic"],"weaknesses":["open mind"],"speed":[{"type":"land","speed":40}],"melee":"ogre hook +21 (3d6+7/x3) or 2 slams +21 (2d8+7 plus 1d6 electricity)","ranged":"double crossbow +12 (2d6/19-20 plus 2d6)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"berserk"},{"type":"knockback"},{"type":"rage","details":"14 rounds/day"},{"type":"rage powers","details":"knockback, moment of clarity, renewed vigor  [1d8+2 hp]"}],"strength":25,"dexterity":9,"intelligence":7,"wisdom":11,"charisma":12,"baseatk":15,"cmb":23,"cmb_special":"+25 bull rush","cmd":32,"cmd_special":"34 vs. bull rush","feats":[{"feat":"Cleave"},{"feat":"Exotic Weapon Proficiency (double crossbow)"},{"feat":"Improved Bull Rush"},{"feat":"Improved Iron Will"},{"feat":"Intimidating Prowess"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Disguise","value":8},{"skill":"Intimidate","value":18,"special":"+4 against Medium or smaller creatures"},{"skill":"Perception","value":1},{"skill":"Stealth","value":7}],"languages":["Common"],"sq":["fast movement","moment of clarity","renewed vigor  (1/day; 1d8)"],"special_abilities":[{"type":"Berserk","kind":"Ex","details":"When the Beast enters combat, there is a cumulative 5% chance each round that it goes berserk. This increases to 10% per round when using its rage ability. The uncontrolled golem goes on a rampage, attacking the nearest living creature or smashing some object smaller than itself if no creature is within reach, then moving on to spread more destruction. It takes 1 minute of inactivity by the golem to reset its berserk chance to 0%."},{"type":"Immunity to Magic","kind":"Ex","details":"A flesh golem is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against the creature, as noted below. • A magical attack that deals cold or fire damage slows a flesh golem (as the slow spell) for 2d6 rounds (no save). • A magical attack that deals electricity damage breaks any slow effect on the golem and heals 1 point of damage for every 3 points of damage the attack would otherwise deal. If the amount of healing would cause the golem to exceed its full normal hit points, it gains any excess as temporary hit points. A flesh golem gets no saving throw against attacks that deal electricity damage."},{"type":"Knockback","kind":"Ex","details":"The Beast can make one free bull rush attempt against one target hit in melee this round. The Beast doesn't need to move back with the target if successful. This power is used as an immediate action after the attack roll is made."},{"type":"Open Mind","kind":"Ex","details":"Unlike other constructs, the Beast is susceptible to mind-affecting effects (charms, compulsions, phantasms, patterns, and morale effects)."},{"type":"Rage","kind":"Ex","details":"The Beast doesn't gain a bonus to its Constitution while in a rage, nor does it gain any extra hit points. Likewise, it isn't fatigued after rage."}],"gear":"battered masterwork breastplate, double crossbow, ogre hook, boots of the mire, cloak of elvenkind, flesh golem manual, shock amulet of mighty fists, ragged and torn explorer's outfit, headless doll, tattered book of Taldan poetry, aquamarine worth 100 gp.","before_combat":"The Beast tries to avoid combat if at all possible, unless hunting a particular foe.","during_combat":"The Beast begins by attempting to demoralize its target before attacking with its ogre hook. If faced with multiple opponents or ones who seem able to bypass its damage reduction, the Beast rages. While raging or berserk, the Beast has little grasp of tactics, pummeling a single enemy with its fists until it stops moving.","morale":"With no way to heal itself except its renewed vigor rage power, the Beast flees from battle if reduced to less than half its hit points. If berserk, the Beast fights until destroyed.","base_statistics":"When not raging, the Beast's statistics are as follows: AC 25, touch 8, flat-footed 25; Will +8; Melee ogre hook +19/+14/+9 (3d6+5/x3) or 2 slams +19 (2d8+5 plus 1d6 electricity); Str 21; CMB +21 (+23 bull rush); CMD 30 (32 vs. bull rush); Skills Intimidate +16 (+20 against Medium or smaller creatures)","source":"Classic Horrors"},{"name":"Ajekrith, the Nightwing Snat cher","cr":8,"xp":4800,"race":"gargoyle","gender":"Male","age_category":"Adult","classes":[{"class":"rogue","level":4}],"alignment":"CE","size":"Medium","type":"monstrous humanoid","sub_types":["earth"],"init":9,"senses":["darkvision 60 ft."],"ac":21,"ac_touch":16,"ac_flat_footed":21,"ac_mods":"+1 armor, +1 deflection, +5 Dex, +4 natural","hp":63,"hd":"5d10+4d8+18","hd_value":9,"fort":4,"ref":13,"will":5,"defensive_abilities":["evasion","trap sense +1","uncanny dodge"],"dr":"10/magic","speed":[{"type":"fly","speed":60,"maneuverability":"average"},{"type":"land","speed":40}],"melee":"2 claws +13 (1d6+5), bite +13 (1d4+5), gore +13 (1d4+5)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bleeding attack"},{"type":"sneak attack","details":"+2d6"},{"type":"surprise attacks"}],"strength":18,"dexterity":20,"constitution":14,"intelligence":9,"wisdom":10,"charisma":8,"baseatk":8,"cmb":12,"cmd":28,"feats":[{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Fly)"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Acrobatics","value":13,"special":"+4 to jump"},{"skill":"Bluff","value":7},{"skill":"Escape Artist","value":13},{"skill":"Fly","value":20},{"skill":"Intimidate","value":7},{"skill":"Knowledge (local)","value":6},{"skill":"Perception","value":12},{"skill":"Stealth","value":21,"special":"+6 in stony areas"}],"languages":["Common","Terran"],"sq":["freeze","trapfinding"],"special_abilities":[{"type":"Freeze","kind":"Ex","details":"A gargoyle can hold itself so still it appears to be a statue. A gargoyle that uses freeze can take 20 on its Stealth check to hide in plain sight as a stone statue."}],"gear":"amulet of mighty fists +1, bracers of armor +1, ring of protection +1, masterwork thieves' tools, 1,274 gp worth of coins, gems, and jewelry","before_combat":"Ajekrith enjoys perching among carved stone gargoyles and other city decorations, blending in and observing all who pass by. He sometimes waits above an alley or entrance to a spooky church, relying on stealth to give him an advantage against an unsuspecting victim.","during_combat":"Ajekrith prefers to ambush lone prey, silently tracking his target from above. When a choice moment presents itself, he swoops down with a flyby sneak attack. Once a victim is bleeding, Ajekrith pulls back and follows his prey from a distance until it collapses from blood loss. Against foes who fight back, Ajekrith uses Flyby Attack to stay out of range of his opponents' weapons. He only lands to make full attacks if he thinks he can quickly put an opponent out of commission.","morale":"Ajekrith flees if reduced to below 20 hit points, to nurse his wounds and plot his revenge.","source":"Classic Horrors"},{"name":"Ehrimun","cr":14,"xp":38400,"race":"ghoul","gender":"Male","age_category":"Adult","classes":[{"class":"necromancer","level":14}],"alignment":"CE","size":"Medium","type":"undead","init":5,"senses":["darkvision 60 ft.","life sight 20 ft. (14 rounds/day)"],"ac":24,"ac_touch":18,"ac_flat_footed":18,"ac_mods":"+4 armor, +2 deflection, +5 Dex, +1 dodge, +2 natural","hp":152,"hd":"2d8+14d6+94","hd_value":16,"fort":10,"ref":11,"will":17,"defensive_abilities":["channel resistance +2"],"speed":[{"type":"land","speed":30}],"melee":"bite +13 (1d6+1 plus disease and paralysis), 2 claws +13 (1d6+1 plus paralysis)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"paralysis","details":"1d4+1 rounds, DC 15, elves are immune"},{"type":"power over undead","details":"8/day, DC 21"}],"spell_like_abilities_caster_level":14,"spell_like_abilities":[{"frequency":"8/day","spells":[{"spell":"grave touch"}]}],"spellsknown_caster_level":14,"spellsknown":[{"spell_level":7,"spell_slots":2,"spells":[{"spell":"finger of death"},{"spell":"quickened dispel magic"}]},{"spell_level":6,"spell_slots":3,"spells":[{"spell":"circle of death"},{"spell":"quickened false life"},{"spell":"summon monster IV"}]},{"spell_level":5,"spell_slots":5,"spells":[{"spell":"magic jar"},{"spell":"quickened shield"},{"spell":"telekinesis"},{"spell":"teleport"},{"spell":"waves of fatigue"}]},{"spell_level":4,"spell_slots":6,"spells":[{"spell":"arcane eye"},{"spell":"black tentacles"},{"spell":"contagion"},{"spell":"fear"},{"spell":"stoneskin"},{"spell":"summon monster IV"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"dispel magic"},{"spell":"fireball"},{"spell":"gaseous form"},{"spell":"haste"},{"spell":"stinking cloud"},{"spell":"vampiric touch"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"acid arrow"},{"spell":"blindness/deafness"},{"spell":"cat's grace"},{"spell":"detect thoughts"},{"spell":"extended mage armor"},{"spell":"resist energy"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"chill touch"},{"spell":"expeditious retreat"},{"spell":"feather fall"},{"spell":"grease"},{"spell":"obscuring mist"},{"spell":"protection from good"},{"spell":"reduce person"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"light"},{"spell":"mage hand"},{"spell":"read magic"}]}],"prohibited_schools":"enchantment, illusion","strength":13,"dexterity":20,"intelligence":20,"wisdom":16,"charisma":18,"baseatk":8,"cmb":9,"cmd":33,"feats":[{"feat":"Arcane Strike"},{"feat":"Combat Casting"},{"feat":"Command Undead"},{"feat":"Defensive Combat Training"},{"feat":"Dodge"},{"feat":"Extend Spell"},{"feat":"Greater Spell Focus (necromancy)"},{"feat":"Quicken Spell"},{"feat":"Scribe Scroll"},{"feat":"Spell Focus (necromancy)"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":6},{"skill":"Climb","value":6},{"skill":"Fly","value":17},{"skill":"Intimidate","value":10},{"skill":"Knowledge (arcana)","value":24},{"skill":"Knowledge (dungeoneering)","value":24},{"skill":"Knowledge (religion)","value":24},{"skill":"Linguistics","value":14},{"skill":"Perception","value":22},{"skill":"Spellcraft","value":24},{"skill":"Stealth","value":23}],"languages":["Common","Abyssal","Aklo","Dwarven","Elven","Gnome","Goblin","Gug","Necril","Orvian","Osiriani","Undercommon"],"sq":["contingency"],"special_abilities":[{"type":"Arcane Bond","details":"Ehrimun's staff is a unique magic item, capped with the skulls of several halflings and a rune-etched nightmare's skull. It allows the use of the following spells: magic missile (1 charge), ray of enfeeblement (1 charge), ray of exhaustion (2 charges), dimension door (3 charges), and enervation (3 charges)."},{"type":"Contingency","details":"If Ehrimun is reduced to 20 or fewer hit points, a dimension door spell activates and removes him from battle."}],"gear":"staff (arcane bond), belt of incredible dexterity +2, cloak of resistance +2, ring of protection +2, diamond worth 1,500 gp, diamond dust worth 750 gp, wand of fly (25 charges)","before_combat":"Ehrimun summons a minion and casts stoneskin, cat's grace, and protection from good.","during_combat":"Ehrimun leads with circle of death to eliminate many foes, then uses area spells to eliminate survivors.","morale":"Ehrimun relies on his contingency to save him from destruction.","source":"Classic Horrors"},{"name":"Ulla Jarnrygg","cr":10,"xp":9600,"race":"annis hag","gender":"Female","age_category":"Adult","classes":[{"class":"sorcerer","level":9}],"alignment":"CE","size":"Large","type":"monstrous humanoid","init":7,"senses":["darkvision 60 ft."],"ac":27,"ac_touch":13,"ac_flat_footed":24,"ac_mods":"+4 armor, +1 deflection, +3 Dex, +10 natural, -1 size","hp":149,"hd":"7d10+9d6+80","hd_value":16,"fort":13,"ref":14,"will":13,"dr":"2/bludgeoning","resists":["cold  20"],"sr":17,"speed":[{"type":"land","speed":40}],"melee":"bite +18 (1d6+8), 2 claws +18 (1d6+8 plus grab)","ranged":"ray +13 (by spell)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"bloodline arcana","details":"change energy damage spells to cold damage"},{"type":"elemental blast","details":"9d6 cold, Reflex half DC 17, 1/day"},{"type":"elemental ray","details":"1d6+4 cold, 6/day"},{"type":"rend","details":"2 claws, 2d6+12"}],"spell_like_abilities_caster_level":7,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"alter self"},{"spell":"fog cloud"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":8,"spellsknown":[{"spell_level":4,"spell_slots":4,"spells":[{"spell":"elemental body I"},{"spell":"greater invisibility"},{"spell":"ice storm"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"haste"},{"spell":"protection from energy"},{"spell":"ray of exhaustion"},{"spell":"sleet storm"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"bear's endurance"},{"spell":"bull's strength"},{"spell":"gust of wind"},{"spell":"scorching ray"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"burning hands"},{"spell":"chill touch"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"ray of enfeeblement"},{"spell":"ventriloquism"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"bleed"},{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mending"},{"spell":"ray of frost"},{"spell":"touch of fatigue"}]}],"bloodline":"elemental  (water)","strength":27,"dexterity":16,"constitution":20,"intelligence":11,"wisdom":13,"charisma":16,"baseatk":11,"cmb":20,"cmd":34,"feats":[{"feat":"Alertness"},{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Combat Casting"},{"feat":"Eschew Materials"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Intimidating Prowess"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"}],"skills":[{"skill":"Bluff","value":16},{"skill":"Fly","value":0},{"skill":"Intimidate","value":20},{"skill":"Knowledge (arcana)","value":6},{"skill":"Knowledge (planes)","value":4},{"skill":"Linguistics","value":1},{"skill":"Perception","value":18},{"skill":"Sense Motive","value":5},{"skill":"Spellcraft","value":11},{"skill":"Stealth","value":15}],"languages":["Common","Giant","Hallit","Skald"],"sq":["elemental bloodline (water)"],"gear":"ring of protection +1, cloak of resistance +1, boots of the winterlands, brooch of shielding (80 charges), large sack, flensing knives, hammer and iron spikes, iron pot, whetstone, block of salt, 300 gp, potion of cure serious wounds (3), potion of fly","before_combat":"Ulla keeps mage armor active at all times, recasting it as needed. When she has time to prepare for combat, Ulla casts bull's strength, bear's endurance, greater invisibility, and haste.","during_combat":"Ulla hits massed foes with area effect spells like ice storm and sleet storm, and targets strong warriors with ray of exhaustion or ray of enfeeblement. She uses scorching ray and magic missile against ranged attackers. Once in melee combat, Ulla combines her hasted claw attacks with chill touch, making use of greater invisibility to cast spells safely before attacking again with surprise. If surrounded by enemies, she makes use of her elemental blast ability.","morale":"If reduced to below 30 hit points, Ulla casts elemental body I and flees, using fog cloud to cover her escape, returning later to exact revenge on her attackers.","base_statistics":"Without mage armor, Ulla's stats are as follows: AC 23, touch 13, flat-footed 20.","source":"Classic Horrors"},{"name":"Shielseis, Queen of Asps","cr":11,"xp":12800,"race":"mummy","gender":"Female","age_category":"Adult","classes":[{"class":"aristocrat","level":2},{"class":"cleric","level":9}],"alignment":"LE","size":"Medium","type":"undead","init":6,"senses":["darkvision 60 ft."],"auras":["despair (30 ft., paralyzed for 1d4 rounds, Will DC 19 negates)"],"ac":26,"ac_touch":13,"ac_flat_footed":23,"ac_mods":"+3 armor, +2 Dex, +1 dodge, +10 natural","hp":199,"hd":"8d8+9d8+2d8+114","hd_value":19,"fort":13,"ref":7,"will":20,"dr":"5/-","immunities":["undead traits"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":20}],"melee":"slam +21 (1d8+10 plus curse)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"5d6, DC 21,  8/day"}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":9,"spellsprepared":[{"spell_level":5,"spell_slots":3,"spells":[{"spell":"flame strike"},{"spell":"greater command","type":"domain"},{"spell":"summon monster V"}]},{"spell_level":4,"spell_slots":4,"spells":[{"spell":"air walk"},{"spell":"discern lies","type":"domain"},{"spell":"inflict critical wounds"},{"spell":"tongues"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"animate dead"},{"spell":"bestow curse"},{"spell":"nondetection","type":"domain"},{"spell":"speak with dead"},{"spell":"summon monster III"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"enthrall","type":"domain"},{"spell":"inflict moderate wounds","count":2},{"spell":"resist energy"},{"spell":"spiritual weapon"},{"spell":"undetectable alignment"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"command"},{"spell":"comprehend languages"},{"spell":"disguise self","type":"domain"},{"spell":"divine favor"},{"spell":"doom"},{"spell":"protection from good"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":4,"spells":[{"spell":"bleed"},{"spell":"create water"},{"spell":"detect magic"},{"spell":"guidance"}]}],"spelldomains":"Nobility, Trickery","strength":24,"dexterity":14,"intelligence":10,"wisdom":20,"charisma":21,"baseatk":13,"cmb":20,"cmd":33,"feats":[{"feat":"Alignment Channel"},{"feat":"Command Undead"},{"feat":"Deceitful"},{"feat":"Dodge"},{"feat":"Improved Channel"},{"feat":"Improved Initiative"},{"feat":"Leadership"},{"feat":"Persuasive"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Bluff","value":16},{"skill":"Diplomacy","value":12},{"skill":"Disguise","value":15},{"skill":"Heal","value":13},{"skill":"Intimidate","value":12},{"skill":"Knowledge (religion)","value":14},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":13}],"languages":["Osiriani"],"special_abilities":[{"type":"Curse","kind":"Su","details":"Mummy Rot: slam-injury; save Fort DC 16; onset 1 minute; frequency 1 day; effect 1d6 Con and 1d6 Cha; cure -. Mummy rot is both a curse and a disease and can only be cured if the curse is first removed, at which point the disease can be magically removed. Even after the curse element of mummy rot is lifted, a creature suffering from the disease cannot recover naturally over time. Anyone casting a conjuration (healing) spell on the afflicted creature must succeed on a DC 20 caster level check, or the spell is wasted and the healing has no effect. Anyone who dies from mummy rot turns to dust and cannot be raised without a resurrection or greater magic. The save DC is Charisma-based."},{"type":"Despair","kind":"Su","details":"All creatures within a 30-foot radius that see Shielseis must make a DC 19 Will save or be paralyzed by fear for 1d4 rounds. Whether or not the save is successful, that creature cannot be affected again by her despair ability for 24 hours. This is a paralysis and mindaffecting fear effect. The save DC is Charisma-based."}],"gear":"bracers of armor +3, headband of alluring charisma +2, robe of blending","source":"Classic Horrors"}];
